import{_ as a,c as t,o,ae as i}from"./chunks/framework.DNEoaTf_.js";const p=JSON.parse('{"title":"Privacy Policy","description":"","frontmatter":{},"headers":[],"relativePath":"en/privacy.md","filePath":"en/privacy.md"}'),r={name:"en/privacy.md"};function s(n,e,l,c,d,h){return o(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="privacy-policy" tabindex="-1">Privacy Policy <a class="header-anchor" href="#privacy-policy" aria-label="Permalink to &quot;Privacy Policy&quot;">​</a></h1><p>Last Updated: November 24, 2024</p><h2 id="about-data-collection" tabindex="-1">About Data Collection <a class="header-anchor" href="#about-data-collection" aria-label="Permalink to &quot;About Data Collection&quot;">​</a></h2><p>YouTube Watch Thumbnails (the &quot;Extension&quot;) is designed with user privacy as the top priority.</p><h3 id="data-we-collect-and-store" tabindex="-1">Data We Collect and Store <a class="header-anchor" href="#data-we-collect-and-store" aria-label="Permalink to &quot;Data We Collect and Store&quot;">​</a></h3><p>This extension stores the following data in your browser&#39;s local storage:</p><ul><li><strong>Video IDs</strong>: YouTube video IDs for which thumbnails have been displayed (string)</li><li><strong>Extension Settings</strong>: User configuration settings (string)</li></ul><h3 id="data-storage-location" tabindex="-1">Data Storage Location <a class="header-anchor" href="#data-storage-location" aria-label="Permalink to &quot;Data Storage Location&quot;">​</a></h3><p>All data is stored in your browser&#39;s local storage (<code>chrome.storage.local</code> or <code>browser.storage.local</code>).</p><ul><li><strong>No external server transmission</strong>: Never sent to external servers</li><li><strong>Storage location</strong>: Only on your device</li><li><strong>Third-party access</strong>: Impossible</li></ul><h3 id="data-we-don-t-collect" tabindex="-1">Data We Don&#39;t Collect <a class="header-anchor" href="#data-we-don-t-collect" aria-label="Permalink to &quot;Data We Don&#39;t Collect&quot;">​</a></h3><p>This extension does NOT collect or store:</p><ul><li>Login credentials or passwords</li><li>Browsing history outside of YouTube</li><li>Personally identifiable information (name, email address, etc.)</li><li>Usage statistics or analytics</li></ul><h2 id="purpose-of-data-usage" tabindex="-1">Purpose of Data Usage <a class="header-anchor" href="#purpose-of-data-usage" aria-label="Permalink to &quot;Purpose of Data Usage&quot;">​</a></h2><p>Stored data is used solely for:</p><ol><li><strong>Video IDs</strong>: Managing history of recently displayed thumbnails</li><li><strong>Settings</strong>: Preserving user settings and restoring them on next use</li></ol><p>Thumbnail information is fetched from YouTube&#39;s public API and displayed in your browser.</p><h2 id="data-sharing" tabindex="-1">Data Sharing <a class="header-anchor" href="#data-sharing" aria-label="Permalink to &quot;Data Sharing&quot;">​</a></h2><p><strong>This extension does NOT share stored data with any third parties.</strong></p><p>All data is stored locally and is never transmitted externally.</p><h2 id="data-deletion" tabindex="-1">Data Deletion <a class="header-anchor" href="#data-deletion" aria-label="Permalink to &quot;Data Deletion&quot;">​</a></h2><p>Users can delete their data at any time using the following methods:</p><h3 id="clear-browser-storage" tabindex="-1">Clear Browser Storage <a class="header-anchor" href="#clear-browser-storage" aria-label="Permalink to &quot;Clear Browser Storage&quot;">​</a></h3><p>You can delete the extension&#39;s storage data from your browser settings.</p><h3 id="uninstall-extension" tabindex="-1">Uninstall Extension <a class="header-anchor" href="#uninstall-extension" aria-label="Permalink to &quot;Uninstall Extension&quot;">​</a></h3><p>Uninstalling the extension automatically deletes all stored data.</p><h2 id="about-permissions" tabindex="-1">About Permissions <a class="header-anchor" href="#about-permissions" aria-label="Permalink to &quot;About Permissions&quot;">​</a></h2><p>Permissions requested by the Extension and their purposes:</p><table tabindex="0"><thead><tr><th>Permission</th><th>Reason</th></tr></thead><tbody><tr><td><code>tabs</code></td><td>To get YouTube tab information and access video information</td></tr><tr><td><code>storage</code></td><td>To store extension settings</td></tr></tbody></table><h2 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to &quot;Security&quot;">​</a></h2><p>The Extension implements the following security measures:</p><ul><li>All communication uses HTTPS (encrypted communication) only</li><li>External communication is limited to YouTube&#39;s public API only</li><li>Published as open source to ensure code transparency</li></ul><h2 id="children-s-privacy" tabindex="-1">Children&#39;s Privacy <a class="header-anchor" href="#children-s-privacy" aria-label="Permalink to &quot;Children&#39;s Privacy&quot;">​</a></h2><p>The Extension is not directed at children under 13. It does not collect personal data from anyone, regardless of age.</p><h2 id="change-notifications" tabindex="-1">Change Notifications <a class="header-anchor" href="#change-notifications" aria-label="Permalink to &quot;Change Notifications&quot;">​</a></h2><p>If we change this Privacy Policy, we will notify users via extension updates.</p><h2 id="contact" tabindex="-1">Contact <a class="header-anchor" href="#contact" aria-label="Permalink to &quot;Contact&quot;">​</a></h2><p>For privacy-related questions, please contact us at:</p><ul><li>GitHub Issues: <a href="https://github.com/mosunset/youtube_watch_thumbnails/issues" target="_blank" rel="noreferrer">https://github.com/mosunset/youtube_watch_thumbnails/issues</a></li></ul><hr><div class="tip custom-block"><p class="custom-block-title">Transparency</p><p>The Extension is published as open source on <a href="https://github.com/mosunset/youtube_watch_thumbnails" target="_blank" rel="noreferrer">GitHub</a>. You can freely review the code.</p></div>',41)])])}const b=a(r,[["render",s]]);export{p as __pageData,b as default};
